import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:flutter/material.dart';
import '../models/user_model.dart';
import '../services/team_profile_helpers.dart';

class TeamProfileDetails extends StatelessWidget {
  final UserModel usuarioActual;
  final String perfilId;
  final Map<String, dynamic> data;
  const TeamProfileDetails({super.key, required this.usuarioActual, required this.perfilId, required this.data});
  bool get _admin => usuarioActual.rol == AppRoles.admin;
  DocumentReference<Map<String, dynamic>> get _ref => FirebaseFirestore.instance.collection('usuarios').doc(perfilId);
  @override
  Widget build(BuildContext context) {
    final interests = profileTags(data['intereses']);
    final colors = profileTags(data['coloresFavoritos']);
    final badges = data['insigniasAdmin'] is List ? (data['insigniasAdmin'] as List).whereType<Map>().toList() : <Map>[];
    final places = data['lugaresInstalacion'] is List ? (data['lugaresInstalacion'] as List).whereType<Map>().toList() : <Map>[];
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      const SizedBox(height: 18),
      _section(context, 'LO QUE ME GUSTA', Icons.favorite_outline_rounded, () => _editInterests(context), editable: _admin || usuarioActual.id == perfilId),
      const Text('Información opcional, compartida con el equipo.', style: TextStyle(color: Colors.white54, fontSize: 12)),
      const SizedBox(height: 10),
      if (interests.isEmpty && colors.isEmpty) const Text('Aún no ha agregado sus gustos.', style: TextStyle(color: Colors.white60)),
      Wrap(spacing: 7, runSpacing: 5, children: [
        for (final interest in interests) Chip(avatar: const Icon(Icons.favorite_border, size: 16), label: Text(interest)),
        for (final color in colors) Chip(avatar: const Icon(Icons.palette_outlined, size: 16), label: Text(color)),
      ]),
      const SizedBox(height: 16),
      _section(context, 'INSIGNIAS DE ADMINISTRACIÓN', Icons.workspace_premium_outlined, () => _add(context, 'insigniasAdmin', 'Otorgar insignia', 'Nombre de la insignia', 'Motivo del reconocimiento', badges.length), editable: _admin),
      if (badges.isEmpty) const Text('Sin reconocimientos manuales todavía.', style: TextStyle(color: Colors.white60)),
      for (final b in badges) _entry(context, b, 'insigniasAdmin', Icons.verified_outlined),
      const SizedBox(height: 16),
      _section(context, 'LUGARES DE INSTALACIÓN', Icons.location_on_outlined, () => _add(context, 'lugaresInstalacion', 'Agregar lugar', 'Ciudad y estado', 'Proyecto o participación (opcional)', places.length), editable: _admin),
      if (places.isEmpty) const Text('Administración puede agregar la trayectoria de esta persona.', style: TextStyle(color: Colors.white60)),
      for (final p in places) _entry(context, p, 'lugaresInstalacion', Icons.place_outlined),
    ]);
  }
  Widget _section(BuildContext context, String title, IconData icon, VoidCallback action, {required bool editable}) => Row(children: [
    Icon(icon, size: 19, color: const Color(0xFFB7FF2A)), const SizedBox(width: 8),
    Expanded(child: Text(title, style: const TextStyle(fontSize: 11, fontWeight: FontWeight.w800, letterSpacing: .5))),
    if (editable) IconButton(tooltip: title == 'LO QUE ME GUSTA' ? 'Editar mis gustos' : 'Agregar', onPressed: action, icon: Icon(title == 'LO QUE ME GUSTA' ? Icons.edit_outlined : Icons.add_circle_outline)),
  ]);
  Widget _entry(BuildContext context, Map item, String field, IconData icon) => Card(color: const Color(0xFF171217), child: ListTile(
    leading: Icon(icon, color: const Color(0xFFB7FF2A)),
    title: Text(item['nombre']?.toString() ?? '', style: const TextStyle(fontWeight: FontWeight.w700)),
    subtitle: (item['detalle']?.toString() ?? '').isEmpty ? null : Text(item['detalle'].toString()),
    trailing: !_admin ? null : IconButton(tooltip: 'Quitar de este perfil', icon: const Icon(Icons.delete_outline, size: 20), onPressed: () async {
      final yes = await showDialog<bool>(context: context, builder: (c) => AlertDialog(title: const Text('¿Quitar este registro?'), content: Text(item['nombre']?.toString() ?? ''), actions: [TextButton(onPressed: () => Navigator.pop(c, false), child: const Text('Cancelar')), FilledButton(onPressed: () => Navigator.pop(c, true), child: const Text('Quitar'))]));
      if (yes == true && context.mounted) {
        try { await _ref.update({field: FieldValue.arrayRemove([Map<String, dynamic>.from(item)])}); }
        catch (_) { if (context.mounted) _notice(context, 'No se confirmó el cambio. Revisa tu conexión y los permisos de Administración.'); }
      }
    }),
  ));
  Future<void> _editInterests(BuildContext context) async {
    final interests = TextEditingController(text: profileTags(data['intereses']).join(', '));
    final colors = TextEditingController(text: profileTags(data['coloresFavoritos']).join(', '));
    await _form(context, title: 'Mis gustos', first: interests, firstLabel: 'Intereses y cosas que me gustan', firstMax: 400, second: colors, secondLabel: 'Colores favoritos, separados por comas', secondMax: 160, requiredFirst: false, save: () => _ref.update({'intereses': interests.text.trim(), 'coloresFavoritos': colors.text.trim()}));
    interests.dispose(); colors.dispose();
  }
  Future<void> _add(BuildContext context, String field, String title, String label, String detail, int count) async {
    if (!_admin) return;
    if (count >= 60) { _notice(context, 'Este perfil alcanzó 60 registros. Quita uno antes de agregar otro.'); return; }
    final first = TextEditingController(); final second = TextEditingController();
    await _form(context, title: title, first: first, firstLabel: label, firstMax: 100, second: second, secondLabel: detail, secondMax: 200, requiredFirst: true, save: () => _ref.update({field: FieldValue.arrayUnion([{'nombre': first.text.trim(), 'detalle': second.text.trim(), 'otorgadoPor': usuarioActual.id, 'registradoEn': DateTime.now().toUtc().toIso8601String()}])}));
    first.dispose(); second.dispose();
  }
  Future<void> _form(BuildContext context, {required String title, required TextEditingController first, required String firstLabel, required int firstMax, required TextEditingController second, required String secondLabel, required int secondMax, required bool requiredFirst, required Future<void> Function() save}) async {
    bool busy = false; String? error;
    await showDialog<void>(context: context, barrierDismissible: false, builder: (dialog) => StatefulBuilder(builder: (c, update) => PopScope(canPop: !busy, child: AlertDialog(
      title: Text(title), content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [
        TextField(controller: first, maxLength: firstMax, enabled: !busy, decoration: InputDecoration(labelText: firstLabel)),
        TextField(controller: second, maxLength: secondMax, enabled: !busy, maxLines: 2, decoration: InputDecoration(labelText: secondLabel)),
        const Text('No incluyas domicilios de clientes, contraseñas ni información privada.', style: TextStyle(fontSize: 11, color: Colors.white54)),
        if (error != null) Text(error!, style: const TextStyle(color: Colors.orangeAccent)),
      ])), actions: [TextButton(onPressed: busy ? null : () => Navigator.pop(dialog), child: const Text('Cancelar')), FilledButton(onPressed: busy ? null : () async {
        if (requiredFirst && first.text.trim().isEmpty) { update(() => error = 'Escribe un nombre.'); return; }
        update(() {busy = true; error = null;});
        try { await save(); if (dialog.mounted) Navigator.pop(dialog); }
        catch (_) { if (dialog.mounted) update(() {busy = false; error = 'No se guardó. Revisa Internet y los permisos del servidor; el texto sigue aquí.';}); }
      }, child: Text(busy ? 'Guardando…' : 'Guardar'))],
    ))));
  }
  void _notice(BuildContext context, String message) => ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(message)));
}

match /justification_evidence/{userId}/{allPaths=**} {
  allow read: if signedIn() && (request.auth.uid == userId || role() == 'admin');
  allow create: if signedIn() && request.auth.uid == userId
    && request.resource.size <= 5 * 1024 * 1024
    && request.resource.contentType.matches('image/(jpeg|png|webp)');
  allow delete: if signedIn() && (request.auth.uid == userId || role() == 'admin');
}
  allow read: if signedIn() && legacyRoot != 'justification_evidence';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:saunastilo/models/user_model.dart';
import 'package:saunastilo/services/app_action_catalog.dart';
import 'package:saunastilo/services/team_profile_helpers.dart';
import 'package:saunastilo/widgets/team_profile_details.dart';
void main() {
  UserModel user(String role) => UserModel(id: 'worker', nombre: 'Prueba', correo: 'test@example.invalid', rol: role, fechaRegistro: DateTime(2026));
  test('birthday today stays today and past dates move to next year', () {
    expect(nextTeamBirthday(DateTime(2000,9,5),DateTime(2026,9,5,20)),DateTime(2026,9,5));
    expect(nextTeamBirthday(DateTime(2000,1,11),DateTime(2026,9,5)),DateTime(2027,1,11));
  });
  test('February 29 is observed on February 28 in a non-leap year', () {
    expect(nextTeamBirthday(DateTime(2000,2,29),DateTime(2027,1,1)),DateTime(2027,2,28));
    expect(nextTeamBirthday(DateTime(2000,2,29),DateTime(2028,1,1)),DateTime(2028,2,29));
  });
  test('Mexico date and optional interests have deterministic fallbacks', () {
    expect(mexicoToday(DateTime.utc(2026,9,6,2)),DateTime(2026,9,5));
    expect(profileTags(null),isEmpty);
    expect(profileTags(' carpintería, , música '),['carpintería','música']);
  });
  test('all roles can reach people and loans, workers reach justifications', () {
    for (final role in ['admin','maestro','trabajador','almacenista']) {
      final ids = AppActionCatalog.forUser(user(role)).map((a)=>a.id).toList();
      expect(ids,containsAll(['equipo','prestamos','cumpleanos','insignias']));
      expect(ids.contains('justificar'),role!='admin');
      expect(ids.contains('alerta_general'),role=='admin');
      expect(ids.toSet().length,ids.length);
    }
  });
  testWidgets('manual awards are not editable by a worker at phone width', (tester) async {
    tester.view.physicalSize=const Size(375,812); tester.view.devicePixelRatio=1;
    addTearDown(tester.view.resetPhysicalSize); addTearDown(tester.view.resetDevicePixelRatio);
    await tester.pumpWidget(MaterialApp(theme:ThemeData.dark(),home:Scaffold(body:SingleChildScrollView(child:TeamProfileDetails(usuarioActual:user('trabajador'),perfilId:'worker',data:const {'intereses':'Música, Carpintería','coloresFavoritos':'Verde'})))));
    expect(find.byTooltip('Editar mis gustos'),findsOneWidget);
    expect(find.byTooltip('Agregar'),findsNothing);
    expect(tester.takeException(),isNull);
  });
  testWidgets('admin sees independent award and installation actions', (tester) async {
    await tester.pumpWidget(MaterialApp(theme:ThemeData.dark(),home:Scaffold(body:SingleChildScrollView(child:TeamProfileDetails(usuarioActual:user('admin'),perfilId:'other',data:const {})))));
    expect(find.byTooltip('Agregar'),findsNWidgets(2));
    expect(tester.takeException(),isNull);
  });
}

/* Real Web Audio processing, synthetic microphone. No voices, accounts or staff messages. */
const {chromium}=require('playwright');const fs=require('node:fs');
(async()=>{
 fs.mkdirSync('smoke-results',{recursive:true});
 const browser=await chromium.launch({executablePath:'/usr/bin/google-chrome',headless:true,args:['--no-sandbox','--autoplay-policy=no-user-gesture-required']});
 const results=[];
 try{
  for(const rate of [44100,48000]){
   const page=await browser.newPage();await page.goto('http://127.0.0.1:8177/');
   await page.addScriptTag({path:'web/voice-capture.js'});
   const result=await page.evaluate(async rate=>{
    const Native=window.AudioContext;
    window.AudioContext=class extends Native{constructor(){super({sampleRate:rate})}};
    const source=new Native({sampleRate:rate});await source.resume();
    const oscillator=source.createOscillator();oscillator.frequency.value=440;
    const dest=source.createMediaStreamDestination();oscillator.connect(dest);oscillator.start();
    const original=navigator.mediaDevices.getUserMedia.bind(navigator.mediaDevices);
    navigator.mediaDevices.getUserMedia=async()=>dest.stream;
    try{
     await window.saunaVoiceCapture.start(10);
     await new Promise(resolve=>setTimeout(resolve,3500));
     const wav=await window.saunaVoiceCapture.stop();const v=new DataView(wav.buffer,wav.byteOffset,wav.byteLength);
     let crossings=0,prev=0;for(let i=44;i<wav.length;i+=2){const x=v.getInt16(i,true);if(prev<0&&x>=0)crossings++;prev=x;}
     const seconds=(wav.length-44)/48000;return {inputRate:rate,outputRate:v.getUint32(24,true),seconds,frequency:crossings/seconds,tracksStopped:dest.stream.getTracks().every(t=>t.readyState==='ended')};
    }finally{navigator.mediaDevices.getUserMedia=original;window.AudioContext=Native;oscillator.stop();await source.close();await window.saunaVoiceCapture.dispose();}
   },rate);
   results.push(result);
   if(result.outputRate!==24000||result.seconds<3||result.seconds>4.5||Math.abs(result.frequency-440)>10||!result.tracksStopped)throw Error('Audio rate, pitch, duration or microphone release failed.');
   await page.close();
  }
 }finally{fs.writeFileSync('smoke-results/voice-rate-check.json',JSON.stringify(results,null,2));await browser.close();}
 console.log(JSON.stringify(results,null,2));
})().catch(e=>{console.error(e);process.exitCode=1;});

const test=require('node:test');
const fs=require('node:fs');
const {initializeTestEnvironment,assertSucceeds,assertFails}=require('@firebase/rules-unit-testing');
const {doc,setDoc,getDoc,updateDoc,runTransaction,Timestamp}=require('firebase/firestore');
const {ref,uploadBytes,getBytes}=require('firebase/storage');
let env;
test.before(async()=>{
 if(!process.env.FIRESTORE_EMULATOR_HOST||!process.env.FIREBASE_STORAGE_EMULATOR_HOST)throw Error('Only isolated emulators may run this test.');
 env=await initializeTestEnvironment({projectId:'demo-sauna-people',firestore:{rules:fs.readFileSync('firestore.rules','utf8')},storage:{rules:fs.readFileSync('storage.rules','utf8')}});
 await env.withSecurityRulesDisabled(async c=>{
  for(const [id,rol]of [['admin','admin'],['worker','trabajador'],['other','trabajador']])await setDoc(doc(c.firestore(),'usuarios',id),{nombre:id,correo:id+'@example.invalid',rol});
 });
});
test.after(async()=>{if(env)await env.cleanup()});
test('workers edit their own optional interests, never awards or another person',async()=>{
 const db=env.authenticatedContext('worker').firestore();
 await assertSucceeds(updateDoc(doc(db,'usuarios','worker'),{intereses:'Música',coloresFavoritos:'Verde'}));
 await assertFails(updateDoc(doc(db,'usuarios','worker'),{insigniasAdmin:[{nombre:'Autopremio'}]}));
 await assertFails(updateDoc(doc(db,'usuarios','worker'),{lugaresInstalacion:[{nombre:'Falso'}]}));
 await assertFails(updateDoc(doc(db,'usuarios','other'),{intereses:'Cambio ajeno'}));
 await assertFails(updateDoc(doc(db,'usuarios','worker'),{intereses:'x'.repeat(401)}));
});
test('administration grants manual awards and places',async()=>{
 const db=env.authenticatedContext('admin').firestore();
 await assertSucceeds(updateDoc(doc(db,'usuarios','worker'),{insigniasAdmin:[{nombre:'Calidad',detalle:'Trabajo revisado'}],lugaresInstalacion:[{nombre:'La Paz, BCS'}]}));
});
test('first justification can be created transactionally, no false hours',async()=>{
 const db=env.authenticatedContext('worker').firestore();const r=doc(db,'asistencias','worker_20260905');
 await assertSucceeds(runTransaction(db,async t=>{const d=await t.get(r);if(!d.exists())t.set(r,{id:r.id,trabajadorId:'worker',fecha:Timestamp.fromDate(new Date('2026-09-05T18:00:00Z')),estatus:'falta',estatusComida:'ninguna',ubicacionValida:false,motivoFalta:'Motivo privado',estatusJustificacion:'pendiente_revision'});}));
 await assertFails(getDoc(doc(env.authenticatedContext('other').firestore(),'asistencias','worker_20260905')));
 await assertFails(updateDoc(r,{horaEntrada:Timestamp.now()}));
});
test('approved justifications cannot be reopened by workers',async()=>{
 await env.withSecurityRulesDisabled(c=>setDoc(doc(c.firestore(),'asistencias','worker_20260904'),{trabajadorId:'worker',estatusJustificacion:'aprobada',motivoFalta:'Ya revisado'}));
 await assertFails(updateDoc(doc(env.authenticatedContext('worker').firestore(),'asistencias','worker_20260904'),{estatusJustificacion:'pendiente_revision',motivoFalta:'Cambiar'}));
});
test('private evidence denies peers even though legacy and social media remain readable',async()=>{
 const path='justification_evidence/worker/day/evidence.png';
 await assertSucceeds(uploadBytes(ref(env.authenticatedContext('worker').storage(),path),new Uint8Array([137,80,78,71]),{contentType:'image/png'}));
 await assertSucceeds(getBytes(ref(env.authenticatedContext('worker').storage(),path)));
 await assertSucceeds(getBytes(ref(env.authenticatedContext('admin').storage(),path)));
 await assertFails(getBytes(ref(env.authenticatedContext('other').storage(),path)));
 await assertFails(getBytes(ref(env.unauthenticatedContext().storage(),path)));
 await assertFails(uploadBytes(ref(env.authenticatedContext('other').storage(),path),new Uint8Array([1]),{contentType:'image/png'}));
});
